    for c in texto:
        contagem[c] = contagem.get(c, 0) + 1

    for c in texto:                  # 2ª passada preserva a ordem
        if contagem[c] == 1:
            return c
    return None

def mascarar_email(email):
    if "@" not in email:
        return email
    usuario, dominio = email.split("@", 1)
    if len(usuario) <= 1:
        return "*" * len(usuario) + "@" + dominio
    return usuario[0] + "*" * (len(usuario) - 1) + "@" + dominio

