def versao(texto):
    return tuple(int(parte) for parte in texto.split("."))

def vulneravel(instalada, corrigida):
    return versao(instalada) < versao(corrigida)

print(vulneravel("2.4.7", "2.4.49"))    # True
print(vulneravel("2.4.50", "2.4.49"))   # False
print(vulneravel("1.10.0", "1.9.0"))    # False

