from collections import deque

class Limitador:
    def __init__(self, maximo=5, janela=60):
        self.maximo, self.janela = maximo, janela
        self.marcas = {}

    def permitido(self, chave, agora):
        fila = self.marcas.setdefault(chave, deque())
        while fila and agora - fila[0] > self.janela:
            fila.popleft()                 # saiu da janela, não conta mais
        if len(fila) >= self.maximo:
            return False
        fila.append(agora)
        return True

lim = Limitador(maximo=5, janela=60)
print([lim.permitido("10.0.0.9", t) for t in range(6)])
# [True, True, True, True, True, False]
print(lim.permitido("10.0.0.9", 61))   # True, a janela andou
print(lim.permitido("outro-ip", 5))    # True, cada chave tem a sua conta
